static struct wally_psbt *psbt_with_witness(const char *sighex, size_t input,
					    bool corrupt)
{
	struct bitcoin_tx *tx = bitcoin_tx_from_hex(tmpctx, unsigned_tx,
						    strlen(unsigned_tx));
	struct wally_tx_witness_stack *stack;
	u8 *sig = tal_hexdata(tmpctx, sighex, strlen(sighex));

	assert(tx);
	for (size_t i = 0; i < ARRAY_SIZE(spent); i++)
		psbt_input_set_wit_utxo(tx->psbt, i,
					tal_hexdata(tmpctx, spent[i].script,
						    strlen(spent[i].script)),
					amount_sat(spent[i].amount));
	if (corrupt)
		sig[5] ^= 1;
	tal_wally_start();
	assert(wally_tx_witness_stack_init_alloc(1, &stack) == WALLY_OK);
	assert(wally_tx_witness_stack_add(stack, sig, tal_bytelen(sig))
	       == WALLY_OK);
	assert(wally_psbt_input_set_final_witness(&tx->psbt->inputs[input],
						  stack) == WALLY_OK);
	wally_tx_witness_stack_free(stack);
	tal_wally_end(tx->psbt);
	return tx->psbt;
}

int main(int argc, char *argv[])
{
	common_setup(argv[0]);
	chainparams = chainparams_for_network("regtest");

	for (size_t i = 0; i < ARRAY_SIZE(inputs); i++) {
		/* Only these are allowed in a tx_signatures. */
		bool allowed = inputs[i].hash_type == 0x00
			|| inputs[i].hash_type == 0x01;

		for (int unified = 0; unified < 2; unified++) {
			struct wally_psbt *psbt
				= psbt_with_witness(inputs[i].sig,
						    inputs[i].input, false);
			const char *bad
				= psbt_input_witness_invalid(tmpctx, psbt,
							     inputs[i].input,
							     unified);
			assert(allowed == (bad == NULL));
			if (allowed) {
				psbt = psbt_with_witness(inputs[i].sig,
							 inputs[i].input, true);
				assert(psbt_input_witness_invalid(tmpctx, psbt,
								  inputs[i].input,
								  unified));
			}
		}
	}

	common_shutdown();
	return 0;
}
